def transform(grid):
    out = [row[:] for row in grid]
    h = len(grid)
    for r in range(h // 2):
        for c, value in enumerate(grid[r]):
            if value != grid[r][0] and grid[r + h // 2][c] == grid[r + h // 2][0]:
                out[r + h // 2][c] = 1
    return out

